mapper.select:
SELECT a.id, a.student_id, a.class_id, a.attendance_date, a.status, a.create_time, s.student_no, s.name AS student_name, c.class_name FROM attendance a LEFT JOIN student s ON a.student_id = s.id LEFT JOIN class c ON a.class_id = c.id AND c.is_deleted = 0 WHERE a.class_id = #{classId} AND a.is_deleted = 0
AND a.attendance_date >= #{startDate}
AND a.attendance_date <= #{endDate}
ORDER BY a.attendance_date DESC, s.student_no LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM attendance a
WHERE a.class_id = #{classId} AND a.is_deleted = 0

    AND a.attendance_date >= #{startDate}


    AND a.attendance_date <= #{endDate}
